INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 1, 'Combien de couleurs y a-t-il dans un arc-en-ciel ?', '7', ARRAY['5', '6', '8'], 'fr', true, 'Les 7 couleurs sont : rouge, orange, jaune, vert, bleu, indigo et violet.'),
('general', 1, 'Quel est le plus grand ocean du monde ?', 'L''ocean Pacifique', ARRAY['L''ocean Atlantique', 'L''ocean Indien', 'L''ocean Arctique'], 'fr', true, 'L''ocean Pacifique couvre environ un tiers de la surface de la Terre.'),
