('general', 1, 'Quelle est la boisson la plus consommee au monde apres l''eau ?', 'Le the', ARRAY['Le cafe', 'Le lait', 'Le jus d''orange'], 'fr', true, 'Le the est consomme depuis des millenaires, notamment en Asie.'),
('general', 1, 'Quel est le plus long fleuve du monde ?', 'Le Nil', ARRAY['L''Amazone', 'Le Mississippi', 'Le Yangzi Jiang'], 'fr', true, 'Le Nil mesure environ 6 650 km et traverse l''Afrique du sud au nord.'),
