('general', 1, 'Quel est le symbole chimique de l''eau ?', 'H2O', ARRAY['CO2', 'O2', 'NaCl'], 'fr', true, 'H2O signifie deux atomes d''hydrogene et un atome d''oxygene.'),
('general', 1, 'Quel instrument de musique a des touches noires et blanches ?', 'Le piano', ARRAY['La guitare', 'Le violon', 'La flute'], 'fr', true, 'Un piano standard possede 88 touches, dont 52 blanches et 36 noires.'),
('general', 1, 'Quel pays a la forme d''une botte ?', 'L''Italie', ARRAY['La France', 'L''Espagne', 'La Grece'], 'fr', true, 'L''Italie a une forme de botte reconnaissable sur la carte.'),
