('general', 1, 'Comment appelle-t-on le bebe du chat ?', 'Un chaton', ARRAY['Un poussin', 'Un ourson', 'Un faon'], 'fr', true, 'Le chaton est le petit du chat, generalement sevré vers 8 semaines.'),
('general', 1, 'Combien de pattes a une araignee ?', '8', ARRAY['6', '10', '12'], 'fr', true, 'Les araignees sont des arachnides et possedent 8 pattes, contrairement aux insectes qui en ont 6.'),
('general', 1, 'Quelle est la monnaie utilisee en Europe ?', 'L''euro', ARRAY['Le dollar', 'La livre', 'Le franc'], 'fr', true, 'L''euro est la monnaie commune de 20 pays de l''Union europeenne depuis 2002.'),
