('general', 1, 'Quel est le plus haut sommet du monde ?', 'L''Everest', ARRAY['Le Mont Blanc', 'Le Kilimandjaro', 'Le K2'], 'fr', true, 'L''Everest culmine a 8 849 metres dans la chaine de l''Himalaya.'),
('general', 1, 'Quel aliment est fabrique par les abeilles ?', 'Le miel', ARRAY['Le beurre', 'Le sucre', 'La confiture'], 'fr', true, 'Les abeilles produisent du miel a partir du nectar des fleurs.'),
('general', 1, 'Combien font 10 x 10 ?', '100', ARRAY['90', '110', '1000'], 'fr', true, 'Dix fois dix egale cent, un calcul de base en mathematiques.'),
('general', 1, 'Quel jour fete-t-on Noel ?', 'Le 25 decembre', ARRAY['Le 24 decembre', 'Le 31 decembre', 'Le 1er janvier'], 'fr', true, 'Noel se celebre le 25 decembre dans la tradition chretienne.'),
('general', 1, 'Quel est le plus gros fruit a coque ?', 'La noix de coco', ARRAY['La noix', 'L''amande', 'La noisette'], 'fr', true, 'La noix de coco peut peser jusqu''a 2,5 kg et pousse sur le cocotier.'),
