('general', 1, 'Quel monument parisien a ete construit en 1889 ?', 'La Tour Eiffel', ARRAY['L''Arc de Triomphe', 'Le Louvre', 'Notre-Dame'], 'fr', true, 'La Tour Eiffel a ete construite par Gustave Eiffel pour l''Exposition universelle de 1889.'),
('general', 1, 'Combien y a-t-il de voyelles en francais ?', '6', ARRAY['5', '4', '7'], 'fr', true, 'Les voyelles en francais sont : A, E, I, O, U et Y.'),
('general', 1, 'Quel est l''animal le plus grand du monde ?', 'La baleine bleue', ARRAY['L''elephant', 'La girafe', 'Le requin blanc'], 'fr', true, 'La baleine bleue peut mesurer jusqu''a 30 metres et peser 150 tonnes.'),
('general', 1, 'Quelle est la couleur obtenue en melangeant le bleu et le jaune ?', 'Vert', ARRAY['Orange', 'Violet', 'Marron'], 'fr', true, 'En melangeant les couleurs primaires bleu et jaune, on obtient du vert.'),
('general', 1, 'Quel est le jour de la fete nationale francaise ?', 'Le 14 juillet', ARRAY['Le 1er mai', 'Le 8 mai', 'Le 11 novembre'], 'fr', true, 'Le 14 juillet commemore la prise de la Bastille en 1789.'),
