('general', 2, 'Quel est le sport national du Canada ?', 'Le hockey sur glace', ARRAY['Le baseball', 'Le curling', 'Le football americain'], 'fr', true, 'Le hockey sur glace est le sport national d''hiver du Canada depuis 1994.'),
('general', 2, 'Quel instrument mesure la temperature ?', 'Le thermometre', ARRAY['Le barometre', 'L''hygrometre', 'L''anemometre'], 'fr', true, 'Le thermometre mesure la temperature en degres Celsius ou Fahrenheit.'),
