('general', 3, 'Combien de temps dure une annee sur Mars ?', 'Environ 687 jours terrestres', ARRAY['Environ 365 jours', 'Environ 500 jours', 'Environ 900 jours'], 'fr', true, 'Mars etant plus eloignee du Soleil, son orbite est plus longue que celle de la Terre.'),
('general', 3, 'Quel est le nom du phenomene physique qui fait que les aimants s''attirent ?', 'Le magnetisme', ARRAY['La gravite', 'L''electricite statique', 'La force nucleaire'], 'fr', true, 'Le magnetisme est une force fondamentale liee au mouvement des charges electriques.'),
('general', 3, 'Quelle est la capitale de la Nouvelle-Zelande ?', 'Wellington', ARRAY['Auckland', 'Christchurch', 'Queenstown'], 'fr', true, 'Wellington est la capitale de la Nouvelle-Zelande depuis 1865.'),
('general', 3, 'Quel est le nom du plus grand recif corallien du monde ?', 'La Grande Barriere de corail', ARRAY['Le recif de Belize', 'Le recif de la Mer Rouge', 'Le recif de Nouvelle-Caledonie'], 'fr', true, 'La Grande Barriere de corail s''etend sur 2 300 km le long de la cote australienne.'),
('general', 3, 'Quel pays est le plus grand producteur de diamants ?', 'La Russie', ARRAY['Le Botswana', 'L''Afrique du Sud', 'Le Congo'], 'fr', true, 'La Russie produit environ 30% des diamants bruts mondiaux.'),
('general', 3, 'Combien d''elements chimiques le tableau periodique contient-il ?', '118', ARRAY['108', '112', '126'], 'fr', true, 'Le tableau periodique contient 118 elements chimiques, du plus leger (hydrogene) au plus lourd (oganesson).'),
('general', 3, 'Quel est le plus petit os du corps humain ?', 'L''etrier', ARRAY['Le marteau', 'L''enclume', 'Le pisiforme'], 'fr', true, 'L''etrier se trouve dans l''oreille moyenne et ne mesure que 3 mm.'),
('general', 3, 'Quel celebre physicien a formule E=mc2 ?', 'Albert Einstein', ARRAY['Isaac Newton', 'Niels Bohr', 'Max Planck'], 'fr', true, 'Albert Einstein a publie sa theorie de la relativite restreinte en 1905.'),
('general', 3, 'Quel est le nom du premier homme a avoir marche sur la Lune ?', 'Neil Armstrong', ARRAY['Buzz Aldrin', 'Youri Gagarine', 'John Glenn'], 'fr', true, 'Neil Armstrong a pose le pied sur la Lune le 20 juillet 1969 lors de la mission Apollo 11.'),
('general', 3, 'Quelle est l''unite de mesure de la pression atmospherique ?', 'Le pascal', ARRAY['Le newton', 'Le joule', 'Le watt'], 'fr', true, 'Le pascal (Pa) est l''unite SI de pression, nommee en l''honneur de Blaise Pascal.'),
('general', 3, 'Quel est le plus vieux fromage connu au monde ?', 'Le fromage de brebis', ARRAY['Le gouda', 'Le cheddar', 'Le camembert'], 'fr', true, 'Des traces de fromage datant de 7 000 ans ont ete retrouvees en Pologne.'),
('general', 3, 'Quel est le pays qui compte le plus de langues officielles ?', 'L''Afrique du Sud', ARRAY['L''Inde', 'La Suisse', 'La Belgique'], 'fr', true, 'L''Afrique du Sud reconnait 11 langues officielles.'),
('general', 3, 'Combien de tentacules possede une pieuvre ?', '8', ARRAY['6', '10', '12'], 'fr', true, 'La pieuvre possede 8 tentacules, chacun dote de ventouses.'),
('general', 3, 'Quel est le nom du plus grand volcan du systeme solaire ?', 'Olympus Mons', ARRAY['Le Mauna Kea', 'Le Vesuve', 'Le Piton de la Fournaise'], 'fr', true, 'Olympus Mons sur Mars culmine a environ 21 km, soit presque 3 fois l''Everest.'),
('general', 3, 'Quel est le nom de la proteine qui transporte l''oxygene dans le sang ?', 'L''hemoglobine', ARRAY['L''insuline', 'Le collagene', 'La keratine'], 'fr', true, 'L''hemoglobine se trouve dans les globules rouges et donne au sang sa couleur rouge.'),
('general', 3, 'Quelle est la monnaie du Royaume-Uni ?', 'La livre sterling', ARRAY['L''euro', 'Le dollar', 'Le franc'], 'fr', true, 'La livre sterling est la plus ancienne monnaie encore en circulation.'),
('general', 3, 'En quelle annee l''homme a-t-il marche sur la Lune pour la premiere fois ?', '1969', ARRAY['1965', '1971', '1973'], 'fr', true, 'La mission Apollo 11 a atteint la Lune le 20 juillet 1969.'),
('general', 3, 'Quel est l''organe le plus gros du corps humain apres la peau ?', 'Le foie', ARRAY['Le cerveau', 'Les poumons', 'L''estomac'], 'fr', true, 'Le foie pese environ 1,5 kg et remplit plus de 500 fonctions differentes.'),
('general', 3, 'Quel est le nom du plus celebre tableau de Leonard de Vinci ?', 'La Joconde', ARRAY['La Cene', 'L''Homme de Vitruve', 'La Vierge aux rochers'], 'fr', true, 'La Joconde, ou Mona Lisa, est exposee au musee du Louvre a Paris.'),
('general', 3, 'Quelle est la vitesse du son dans l''air ?', 'Environ 340 m/s', ARRAY['Environ 100 m/s', 'Environ 500 m/s', 'Environ 1000 m/s'], 'fr', true, 'La vitesse du son dans l''air a 20 degres Celsius est d''environ 343 m/s.'),
('general', 3, 'Quel pays a ete le premier a accorder le droit de vote aux femmes ?', 'La Nouvelle-Zelande', ARRAY['La Finlande', 'La Norvege', 'Le Royaume-Uni'], 'fr', true, 'La Nouvelle-Zelande a accorde le droit de vote aux femmes en 1893.'),
('general', 3, 'Combien de fuseaux horaires y a-t-il dans le monde ?', '24', ARRAY['12', '36', '48'], 'fr', true, 'La Terre est divisee en 24 fuseaux horaires correspondant aux 24 heures d''une journee.'),
('general', 3, 'Quel est le nom du premier antibiotique decouvert ?', 'La penicilline', ARRAY['L''amoxicilline', 'La streptomycine', 'L''erythromycine'], 'fr', true, 'Alexander Fleming a decouvert la penicilline par hasard en 1928.'),
('general', 3, 'Quel est le pays le plus visite au monde ?', 'La France', ARRAY['L''Espagne', 'Les Etats-Unis', 'L''Italie'], 'fr', true, 'La France accueille environ 90 millions de touristes par an.'),
('general', 3, 'Quelle est la duree moyenne d''un cycle lunaire ?', 'Environ 29,5 jours', ARRAY['Environ 24 jours', 'Environ 31 jours', 'Environ 35 jours'], 'fr', true, 'Le cycle lunaire dure exactement 29 jours, 12 heures et 44 minutes.'),
('general', 3, 'Quel est le plus grand aeroport du monde en superficie ?', 'L''aeroport du Roi Fahd en Arabie saoudite', ARRAY['L''aeroport de Denver', 'L''aeroport de Dallas', 'L''aeroport de Pekin-Daxing'], 'fr', true, 'L''aeroport du Roi Fahd couvre 776 km2, plus grand que le Bahrein.'),
('general', 3, 'Quel est le nombre d''or ?', 'Environ 1,618', ARRAY['Environ 2,718', 'Environ 3,14', 'Environ 1,414'], 'fr', true, 'Le nombre d''or, aussi appele phi, apparait dans de nombreux phenomenes naturels et oeuvres d''art.'),
('general', 3, 'Quel pays a le plus long littoral au monde ?', 'Le Canada', ARRAY['L''Australie', 'La Russie', 'L''Indonesie'], 'fr', true, 'Le littoral canadien mesure environ 202 080 km, le plus long au monde.'),
('general', 3, 'Quelle est la plus ancienne universite du monde encore en activite ?', 'L''Universite Al Quaraouiyine au Maroc', ARRAY['L''Universite de Bologne', 'L''Universite d''Oxford', 'L''Universite de Paris'], 'fr', true, 'Fondee en 859 a Fes au Maroc, elle est reconnue par le Guinness comme la plus ancienne.'),
('general', 3, 'Quel est le nom de la couche d''ozone dans l''atmosphere ?', 'La stratosphere', ARRAY['La troposphere', 'La mesosphere', 'La thermosphere'], 'fr', true, 'La couche d''ozone se situe dans la stratosphere, entre 20 et 50 km d''altitude.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 4, 'Quelle est la langue la plus parlee au monde en tant que langue maternelle ?', 'Le mandarin', ARRAY['L''anglais', 'L''espagnol', 'L''hindi'], 'fr', true, 'Le mandarin est la langue maternelle de plus de 900 millions de personnes.'),
('general', 4, 'Quel est le nom de la particule elementaire responsable de la masse ?', 'Le boson de Higgs', ARRAY['Le photon', 'Le neutron', 'Le gluon'], 'fr', true, 'Le boson de Higgs a ete decouvert au CERN en 2012, confirmant le modele standard.'),
('general', 4, 'Quel est le nom de l''effet par lequel un observateur percoit un changement de frequence d''une onde ?', 'L''effet Doppler', ARRAY['L''effet Compton', 'L''effet Venturi', 'L''effet de serre'], 'fr', true, 'L''effet Doppler explique pourquoi le son d''une ambulance change quand elle passe pres de nous.'),
('general', 4, 'Quel est le seul metal liquide a temperature ambiante autre que le mercure ?', 'Le gallium', ARRAY['Le cesium', 'Le francium', 'Le rubidium'], 'fr', true, 'Le gallium fond a seulement 29,76 degres Celsius, juste en dessous de la temperature corporelle.'),
('general', 4, 'Combien de pays sont membres de l''Union europeenne en 2024 ?', '27', ARRAY['25', '28', '30'], 'fr', true, 'L''UE compte 27 membres depuis le Brexit du Royaume-Uni en 2020.'),
('general', 4, 'Quel est le nom du plus ancien systeme d''ecriture connu ?', 'Le cuneiforme', ARRAY['Les hieroglyphes', 'L''alphabet phenicien', 'Le sanscrit'], 'fr', true, 'Le cuneiforme a ete invente par les Sumeriens vers 3400 avant J.-C. en Mesopotamie.'),
('general', 4, 'Quelle est la constante gravitationnelle universelle ?', '6,674 x 10^-11 N.m2/kg2', ARRAY['9,81 m/s2', '3 x 10^8 m/s', '1,38 x 10^-23 J/K'], 'fr', true, 'La constante G a ete mesuree pour la premiere fois par Henry Cavendish en 1798.'),
('general', 4, 'Quel pays a le plus de sites classes au patrimoine mondial de l''UNESCO ?', 'L''Italie', ARRAY['La Chine', 'L''Espagne', 'La France'], 'fr', true, 'L''Italie possede 58 sites UNESCO, devant la Chine et l''Allemagne.'),
('general', 4, 'Quel est le nom du plus grand organisme vivant sur Terre ?', 'Le champignon Armillaria ostoyae', ARRAY['La baleine bleue', 'Le sequoia geant', 'Le peuplier faux-tremble'], 'fr', true, 'Ce champignon de l''Oregon couvre 9,6 km2 et a plus de 2 400 ans.'),
('general', 4, 'Quelle est la temperature la plus basse theoriquement possible ?', '-273,15 degres Celsius', ARRAY['-300 degres Celsius', '-250 degres Celsius', '-200 degres Celsius'], 'fr', true, 'Le zero absolu (-273,15 degres C ou 0 Kelvin) est la limite inferieure de temperature.'),
('general', 4, 'Quel est le nom de la theorie scientifique sur l''origine de l''univers ?', 'Le Big Bang', ARRAY['La theorie de l''etat stationnaire', 'La theorie des cordes', 'Le modele cyclique'], 'fr', true, 'Le Big Bang decrit l''expansion de l''univers a partir d''un etat extremement dense il y a 13,8 milliards d''annees.'),
('general', 4, 'Quel est le plus long tunnel ferroviaire du monde ?', 'Le tunnel de base du Gothard', ARRAY['Le tunnel sous la Manche', 'Le tunnel du Simplon', 'Le tunnel Seikan'], 'fr', true, 'Le tunnel du Gothard en Suisse mesure 57,1 km et a ete inaugure en 2016.'),
('general', 4, 'Quel est le nom de la force qui maintient les electrons autour du noyau atomique ?', 'La force electromagnetique', ARRAY['La force gravitationnelle', 'La force nucleaire forte', 'La force nucleaire faible'], 'fr', true, 'La force electromagnetique attire les electrons charges negativement vers le noyau charge positivement.'),
('general', 4, 'Quel est le plus grand lac d''eau douce du monde en surface ?', 'Le lac Superieur', ARRAY['Le lac Victoria', 'Le lac Baikal', 'Le lac Huron'], 'fr', true, 'Le lac Superieur couvre 82 100 km2, a la frontiere entre les Etats-Unis et le Canada.'),
('general', 4, 'Quel est le nom du processus biologique par lequel une cellule se divise en deux ?', 'La mitose', ARRAY['La meiose', 'La cytokinese', 'L''apoptose'], 'fr', true, 'La mitose produit deux cellules filles genetiquement identiques a la cellule mere.'),
('general', 4, 'Quel mathematicien a demontre le dernier theoreme de Fermat ?', 'Andrew Wiles', ARRAY['Pierre de Fermat', 'Carl Gauss', 'Leonard Euler'], 'fr', true, 'Andrew Wiles a publie sa demonstration en 1995, apres 358 ans de recherches.'),
('general', 4, 'Quel est le nom de l''isotope d''hydrogene utilise dans la fusion nucleaire ?', 'Le deuterium', ARRAY['Le tritium', 'Le protium', 'L''helium-3'], 'fr', true, 'Le deuterium contient un proton et un neutron, et est utilise dans les reacteurs a fusion.'),
('general', 4, 'Quelle est la plus petite particule de matiere ordinaire ?', 'Le quark', ARRAY['L''electron', 'Le proton', 'Le neutron'], 'fr', true, 'Les quarks sont les constituants elementaires des protons et des neutrons.'),
('general', 4, 'Quel empire a ete le plus vaste de l''histoire ?', 'L''Empire britannique', ARRAY['L''Empire mongol', 'L''Empire romain', 'L''Empire russe'], 'fr', true, 'L''Empire britannique a couvert jusqu''a 35 millions de km2, soit un quart des terres emergees.'),
('general', 4, 'Quel est le nom du phenomene physique ou la lumiere change de direction en passant d''un milieu a un autre ?', 'La refraction', ARRAY['La reflexion', 'La diffraction', 'L''absorption'], 'fr', true, 'La refraction explique pourquoi un baton semble brise quand il est plonge dans l''eau.'),
('general', 4, 'Quel scientifique a decouvert la radioactivite ?', 'Henri Becquerel', ARRAY['Marie Curie', 'Pierre Curie', 'Wilhelm Rontgen'], 'fr', true, 'Henri Becquerel a decouvert la radioactivite par hasard en 1896 en etudiant l''uranium.'),
('general', 4, 'Quel est le nom de la loi physique qui stipule que tout corps plonge dans un fluide subit une poussee ?', 'Le principe d''Archimede', ARRAY['La loi de Pascal', 'La loi de Bernoulli', 'La loi de Boyle'], 'fr', true, 'Archimede aurait decouvert ce principe en prenant son bain, s''ecriant Eureka.'),
('general', 4, 'Combien de langues officielles l''ONU reconnait-elle ?', '6', ARRAY['4', '5', '8'], 'fr', true, 'Les 6 langues officielles sont : anglais, francais, espagnol, russe, chinois et arabe.'),
('general', 4, 'Quel est le nom du plus ancien code de lois connu ?', 'Le Code de Hammurabi', ARRAY['Le Code de Justinien', 'La Loi des Douze Tables', 'Le Code Napoleon'], 'fr', true, 'Le Code de Hammurabi date d''environ 1754 avant J.-C. et vient de Babylone.'),
('general', 4, 'Quel est le nom de la plus profonde fosse oceanique ?', 'La fosse des Mariannes', ARRAY['La fosse de Porto Rico', 'La fosse des Tonga', 'La fosse des Kouriles'], 'fr', true, 'La fosse des Mariannes atteint 10 994 metres au point Challenger Deep.'),
('general', 4, 'Quel est le nom du phenomene ou un liquide se transforme directement en gaz sans passer par l''ebullition ?', 'L''evaporation', ARRAY['La sublimation', 'La condensation', 'La vaporisation'], 'fr', true, 'L''evaporation se produit a la surface d''un liquide a toute temperature.'),
('general', 4, 'Quel est le plus grand producteur mondial de petrole ?', 'Les Etats-Unis', ARRAY['L''Arabie Saoudite', 'La Russie', 'La Chine'], 'fr', true, 'Les Etats-Unis sont devenus le premier producteur mondial de petrole grace au schiste.'),
('general', 4, 'Quel est le nom de la theorie qui unifie l''electricite et le magnetisme ?', 'L''electromagnetisme', ARRAY['La relativite', 'La mecanique quantique', 'La thermodynamique'], 'fr', true, 'James Clerk Maxwell a unifie l''electricite et le magnetisme en 1865 avec ses equations.'),
('general', 4, 'Quelle est la duree de vie moyenne d''un globule rouge ?', 'Environ 120 jours', ARRAY['Environ 30 jours', 'Environ 60 jours', 'Environ 365 jours'], 'fr', true, 'Les globules rouges vivent environ 120 jours avant d''etre recycles par la rate.'),
('general', 4, 'Quel est le nom de la premiere femme dans l''espace ?', 'Valentina Terechkova', ARRAY['Sally Ride', 'Mae Jemison', 'Svetlana Savitskaia'], 'fr', true, 'Valentina Terechkova a vole dans l''espace le 16 juin 1963 a bord de Vostok 6.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 5, 'Quelle est la relation entre la suite de Fibonacci et le nombre d''or ?', 'Le rapport de deux termes consecutifs converge vers le nombre d''or', ARRAY['Les termes de Fibonacci sont des multiples du nombre d''or', 'La somme de la suite est egale au nombre d''or', 'Le nombre d''or est la racine de la suite'], 'fr', true, 'En divisant chaque terme par le precedent, on obtient une valeur qui tend vers phi (1,618...).'),
('general', 5, 'Quel est le principe d''incertitude de Heisenberg ?', 'On ne peut pas connaitre simultanement la position et la vitesse exactes d''une particule', ARRAY['L''observation modifie toujours le resultat d''une experience', 'Rien ne peut depasser la vitesse de la lumiere', 'L''energie ne peut etre ni creee ni detruite'], 'fr', true, 'Ce principe fondamental de la mecanique quantique a ete formule en 1927.'),
('general', 5, 'Quel est le paradoxe de Fermi ?', 'La contradiction entre la probabilite elevee de civilisations extraterrestres et l''absence de contact', ARRAY['L''impossibilite de voyager plus vite que la lumiere', 'Le fait que l''univers soit en expansion acceleree', 'La contradiction entre relativite et mecanique quantique'], 'fr', true, 'Enrico Fermi a pose la question : Si l''univers est si grand, ou sont les extraterrestres ?'),
('general', 5, 'Quel est le nom du probleme mathematique du millenaire resolu par Grigori Perelman ?', 'La conjecture de Poincare', ARRAY['L''hypothese de Riemann', 'Le probleme P vs NP', 'Les equations de Navier-Stokes'], 'fr', true, 'Perelman a demontre la conjecture de Poincare en 2003 et a refuse la medaille Fields.'),
('general', 5, 'Qu''est-ce que l''intrication quantique ?', 'Une correlation instantanee entre particules quelle que soit la distance', ARRAY['La superposition d''etats quantiques', 'Le passage d''une particule a travers une barriere', 'L''annihilation d''une particule et son antiparticule'], 'fr', true, 'Einstein appelait ce phenomene l''action fantomatique a distance.'),
('general', 5, 'Quel est le nom de la constante qui mesure la vitesse d''expansion de l''univers ?', 'La constante de Hubble', ARRAY['La constante de Planck', 'La constante de Boltzmann', 'La constante cosmologique'], 'fr', true, 'La constante de Hubble est d''environ 70 km/s/Mpc et fait l''objet de debats scientifiques.'),
('general', 5, 'Quel est le theoreme d''incompletude de Godel ?', 'Tout systeme formel coherent contient des propositions indecidables', ARRAY['Toute theorie mathematique contient des erreurs', 'Les mathematiques ne peuvent pas decrire la realite', 'Il existe des nombres qui ne peuvent pas etre calcules'], 'fr', true, 'Kurt Godel a demontre ce theoreme en 1931, revolutionnant la logique mathematique.'),
('general', 5, 'Quel est le nom de l''horizon des evenements ?', 'La frontiere d''un trou noir au-dela de laquelle rien ne peut s''echapper', ARRAY['La limite de l''univers observable', 'Le point le plus eloigne atteint par la lumiere', 'La distance maximale entre deux galaxies'], 'fr', true, 'Au-dela de l''horizon des evenements, meme la lumiere ne peut echapper a la gravite du trou noir.'),
('general', 5, 'Quel est le paradoxe des jumeaux en relativite restreinte ?', 'Un jumeau voyageant a grande vitesse vieillit moins vite que celui reste sur Terre', ARRAY['Deux jumeaux ne peuvent pas naitre au meme instant', 'La masse d''un objet diminue avec la vitesse', 'Le temps s''arrete a la vitesse de la lumiere'], 'fr', true, 'Ce paradoxe illustre la dilatation du temps predite par la theorie d''Einstein.'),
('general', 5, 'Quel est le nom du dernier theoreme prouve par Andrew Wiles en 1995 ?', 'Le dernier theoreme de Fermat', ARRAY['Le theoreme de Pythagore generalise', 'Le grand theoreme de Gauss', 'Le theoreme fondamental de l''algebre'], 'fr', true, 'Ce theoreme affirme que a^n + b^n = c^n n''a pas de solution entiere pour n superieur a 2.'),
('general', 5, 'Quelle est la densite critique de l''univers ?', 'Environ 9,47 x 10^-27 kg/m3', ARRAY['Environ 1 kg/m3', 'Environ 10^-10 kg/m3', 'Environ 10^-35 kg/m3'], 'fr', true, 'La densite critique determine si l''univers est ouvert, ferme ou plat.'),
('general', 5, 'Quel est le plus ancien texte litteraire connu ?', 'L''Epopee de Gilgamesh', ARRAY['L''Iliade d''Homere', 'Les Vedas', 'Le Livre des Morts egyptien'], 'fr', true, 'L''Epopee de Gilgamesh date d''environ 2100 avant J.-C. et provient de Mesopotamie.'),
('general', 5, 'Quel est le nom du processus par lequel les etoiles produisent de l''energie ?', 'La fusion nucleaire', ARRAY['La fission nucleaire', 'La combustion', 'La radioactivite'], 'fr', true, 'Les etoiles fusionnent l''hydrogene en helium, liberant d''enormes quantites d''energie.'),
('general', 5, 'Quel est le nom de l''experience de pensee du chat de Schrodinger ?', 'Un chat est a la fois mort et vivant tant qu''on n''observe pas', ARRAY['Un chat peut traverser un mur par effet tunnel', 'Un chat peut se teleporter entre deux boites', 'Un chat vieillit plus lentement en mouvement'], 'fr', true, 'Cette experience illustre l''absurdite apparente de la superposition quantique appliquee au monde macroscopique.'),
('general', 5, 'Quelle est la masse approximative du proton ?', '1,67 x 10^-27 kg', ARRAY['9,11 x 10^-31 kg', '1,67 x 10^-24 kg', '6,64 x 10^-27 kg'], 'fr', true, 'Le proton est environ 1836 fois plus massif que l''electron.'),
('general', 5, 'Quel est le nom du dilemme ethique ou un tramway fonce vers cinq personnes ?', 'Le dilemme du tramway', ARRAY['Le paradoxe du prisonnier', 'Le problème du passager clandestin', 'Le dilemme de Newcomb'], 'fr', true, 'Le dilemme du tramway a ete formule par Philippa Foot en 1967 pour explorer l''ethique.'),
('general', 5, 'Quelle est la temperature du rayonnement cosmique de fond ?', 'Environ 2,7 Kelvin', ARRAY['Environ 0 Kelvin', 'Environ 10 Kelvin', 'Environ 100 Kelvin'], 'fr', true, 'Le fond diffus cosmologique est un vestige du Big Bang decouvert en 1965.'),
('general', 5, 'Quel est le nom de la conjecture mathematique qui affirme que tout nombre pair superieur a 2 est la somme de deux nombres premiers ?', 'La conjecture de Goldbach', ARRAY['La conjecture de Riemann', 'La conjecture de Collatz', 'La conjecture de Poincare'], 'fr', true, 'Formulee en 1742 par Christian Goldbach, elle reste non demontree a ce jour.'),
('general', 5, 'Quel est le nom du principe thermodynamique selon lequel l''entropie d''un systeme isole ne peut qu''augmenter ?', 'Le deuxieme principe de la thermodynamique', ARRAY['Le premier principe', 'Le troisieme principe', 'Le principe zero'], 'fr', true, 'Ce principe explique pourquoi les processus naturels sont irreversibles.'),
('general', 5, 'Quel est le nom de la singularite situee au centre d''un trou noir ?', 'La singularite gravitationnelle', ARRAY['L''horizon des evenements', 'L''ergosphere', 'La photosphere'], 'fr', true, 'A la singularite, la densite et la courbure de l''espace-temps deviennent infinies selon la relativite generale.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 1, 'How many colors are there in a rainbow?', '7', ARRAY['5', '6', '8'], 'en', true, 'The 7 colors are: red, orange, yellow, green, blue, indigo, and violet.'),
('general', 1, 'What is the largest ocean on Earth?', 'The Pacific Ocean', ARRAY['The Atlantic Ocean', 'The Indian Ocean', 'The Arctic Ocean'], 'en', true, 'The Pacific Ocean covers about one-third of the Earth''s surface.'),
('general', 1, 'What is the capital of the United States?', 'Washington, D.C.', ARRAY['New York', 'Los Angeles', 'Chicago'], 'en', true, 'Washington, D.C. has been the capital of the United States since 1790.'),
('general', 1, 'How many days are there in a year?', '365', ARRAY['360', '364', '366'], 'en', true, 'A regular year has 365 days, while a leap year has 366.'),
('general', 1, 'What planet is closest to the Sun?', 'Mercury', ARRAY['Venus', 'Mars', 'Earth'], 'en', true, 'Mercury is the first planet in the solar system, about 58 million km from the Sun.'),
('general', 1, 'What is the hardest natural substance on Earth?', 'Diamond', ARRAY['Gold', 'Iron', 'Quartz'], 'en', true, 'Diamond scores a 10 on the Mohs hardness scale, the highest possible rating.'),
('general', 1, 'What animal is known as the king of the jungle?', 'The lion', ARRAY['The tiger', 'The elephant', 'The gorilla'], 'en', true, 'The lion is often called the king of the jungle because of its majestic mane.'),
('general', 1, 'How many continents are there on Earth?', '7', ARRAY['5', '6', '8'], 'en', true, 'The 7 continents are: Africa, Antarctica, Asia, Europe, North America, South America, and Oceania.'),
('general', 1, 'What is the smallest country in the world?', 'Vatican City', ARRAY['Monaco', 'Malta', 'Liechtenstein'], 'en', true, 'Vatican City is only 0.44 km2 and is located in the heart of Rome.'),
('general', 1, 'What gas do plants absorb for photosynthesis?', 'Carbon dioxide', ARRAY['Oxygen', 'Nitrogen', 'Hydrogen'], 'en', true, 'Plants convert CO2 and sunlight into oxygen and glucose.'),
('general', 1, 'How many months are there in a year?', '12', ARRAY['10', '11', '13'], 'en', true, 'A year is divided into 12 months, from January to December.'),
('general', 1, 'What is the most precious metal traditionally?', 'Gold', ARRAY['Silver', 'Platinum', 'Copper'], 'en', true, 'Gold has been used since antiquity as currency and a symbol of wealth.'),
('general', 1, 'What organ allows you to see?', 'The eye', ARRAY['The ear', 'The nose', 'The mouth'], 'en', true, 'The eye captures light and sends signals to the brain to create images.'),
