('general', 4, 'What is the oldest known writing system?', 'Cuneiform', ARRAY['Hieroglyphics', 'The Phoenician alphabet', 'Sanskrit'], 'en', true, 'Cuneiform was invented by the Sumerians around 3400 BC in Mesopotamia.'),
('general', 4, 'Which country has the most UNESCO World Heritage Sites?', 'Italy', ARRAY['China', 'Spain', 'France'], 'en', true, 'Italy has 58 UNESCO sites, ahead of China and Germany.'),
('general', 4, 'What is the name of the largest living organism on Earth?', 'The Armillaria ostoyae mushroom', ARRAY['The blue whale', 'The giant sequoia', 'The quaking aspen'], 'en', true, 'This honey fungus in Oregon covers 9.6 km2 and is over 2,400 years old.'),
('general', 4, 'What is the lowest theoretically possible temperature?', '-273.15 degrees Celsius', ARRAY['-300 degrees Celsius', '-250 degrees Celsius', '-200 degrees Celsius'], 'en', true, 'Absolute zero (-273.15 C or 0 Kelvin) is the lower limit of temperature.'),
('general', 4, 'What is the longest railway tunnel in the world?', 'The Gotthard Base Tunnel', ARRAY['The Channel Tunnel', 'The Simplon Tunnel', 'The Seikan Tunnel'], 'en', true, 'The Gotthard Base Tunnel in Switzerland is 57.1 km long and opened in 2016.'),
('general', 4, 'What force keeps electrons orbiting the atomic nucleus?', 'The electromagnetic force', ARRAY['Gravitational force', 'The strong nuclear force', 'The weak nuclear force'], 'en', true, 'The electromagnetic force attracts negatively charged electrons to the positively charged nucleus.'),
('general', 4, 'What is the largest freshwater lake in the world by surface area?', 'Lake Superior', ARRAY['Lake Victoria', 'Lake Baikal', 'Lake Huron'], 'en', true, 'Lake Superior covers 82,100 km2 on the border between the US and Canada.'),
('general', 4, 'What is the biological process by which a cell divides into two?', 'Mitosis', ARRAY['Meiosis', 'Cytokinesis', 'Apoptosis'], 'en', true, 'Mitosis produces two daughter cells genetically identical to the parent cell.'),
('general', 4, 'Which mathematician proved Fermat''s Last Theorem?', 'Andrew Wiles', ARRAY['Pierre de Fermat', 'Carl Gauss', 'Leonhard Euler'], 'en', true, 'Andrew Wiles published his proof in 1995, after 358 years of research.'),
('general', 4, 'What is the smallest particle of ordinary matter?', 'The quark', ARRAY['The electron', 'The proton', 'The neutron'], 'en', true, 'Quarks are the elementary constituents of protons and neutrons.'),
('general', 4, 'Which empire was the largest in history?', 'The British Empire', ARRAY['The Mongol Empire', 'The Roman Empire', 'The Russian Empire'], 'en', true, 'The British Empire covered up to 35 million km2, a quarter of the world''s land area.'),
('general', 4, 'What physical phenomenon causes light to change direction when passing from one medium to another?', 'Refraction', ARRAY['Reflection', 'Diffraction', 'Absorption'], 'en', true, 'Refraction explains why a stick appears bent when placed in water.'),
('general', 4, 'Who discovered radioactivity?', 'Henri Becquerel', ARRAY['Marie Curie', 'Pierre Curie', 'Wilhelm Rontgen'], 'en', true, 'Henri Becquerel accidentally discovered radioactivity in 1896 while studying uranium.'),
('general', 4, 'What physical law states that any body immersed in fluid experiences an upward force?', 'Archimedes'' principle', ARRAY['Pascal''s law', 'Bernoulli''s principle', 'Boyle''s law'], 'en', true, 'Archimedes supposedly discovered this principle in his bath and shouted Eureka.'),
('general', 4, 'How many official languages does the United Nations recognize?', '6', ARRAY['4', '5', '8'], 'en', true, 'The 6 official languages are: English, French, Spanish, Russian, Chinese, and Arabic.'),
('general', 4, 'What is the name of the oldest known code of laws?', 'The Code of Hammurabi', ARRAY['The Code of Justinian', 'The Law of the Twelve Tables', 'The Napoleonic Code'], 'en', true, 'The Code of Hammurabi dates from about 1754 BC and comes from Babylon.'),
('general', 4, 'What is the theory that unifies electricity and magnetism?', 'Electromagnetism', ARRAY['Relativity', 'Quantum mechanics', 'Thermodynamics'], 'en', true, 'James Clerk Maxwell unified electricity and magnetism in 1865 with his equations.'),
('general', 4, 'What is the average lifespan of a red blood cell?', 'About 120 days', ARRAY['About 30 days', 'About 60 days', 'About 365 days'], 'en', true, 'Red blood cells live about 120 days before being recycled by the spleen.'),
('general', 4, 'Who was the first woman in space?', 'Valentina Tereshkova', ARRAY['Sally Ride', 'Mae Jemison', 'Svetlana Savitskaya'], 'en', true, 'Valentina Tereshkova flew into space on June 16, 1963, aboard Vostok 6.'),
('general', 4, 'What is the world''s largest producer of petroleum?', 'The United States', ARRAY['Saudi Arabia', 'Russia', 'China'], 'en', true, 'The US became the top oil producer thanks to shale oil extraction.'),
('general', 4, 'What is the name of the scientific theory about the origin of the universe?', 'The Big Bang', ARRAY['Steady State theory', 'String theory', 'Cyclic model'], 'en', true, 'The Big Bang describes the expansion of the universe from an extremely dense state 13.8 billion years ago.'),
('general', 4, 'What is the name of the deepest oceanic trench?', 'The Mariana Trench', ARRAY['The Puerto Rico Trench', 'The Tonga Trench', 'The Kuril Trench'], 'en', true, 'The Mariana Trench reaches 10,994 meters at Challenger Deep.'),
('general', 4, 'What is the name of the phenomenon where a liquid turns directly into gas without boiling?', 'Evaporation', ARRAY['Sublimation', 'Condensation', 'Vaporization'], 'en', true, 'Evaporation occurs at the surface of a liquid at any temperature.'),
('general', 4, 'What is the name of the isotope of hydrogen used in nuclear fusion?', 'Deuterium', ARRAY['Tritium', 'Protium', 'Helium-3'], 'en', true, 'Deuterium contains one proton and one neutron, and is used in fusion reactors.'),
('general', 4, 'What scientific principle states that every action has an equal and opposite reaction?', 'Newton''s Third Law of Motion', ARRAY['The Law of Conservation of Energy', 'Newton''s First Law', 'The Law of Universal Gravitation'], 'en', true, 'Isaac Newton formulated his three laws of motion in 1687 in the Principia.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('general', 5, 'What is the Fibonacci sequence''s relation to the golden ratio?', 'The ratio of consecutive terms converges to the golden ratio', ARRAY['Fibonacci terms are multiples of the golden ratio', 'The sum of the sequence equals the golden ratio', 'The golden ratio is the root of the sequence'], 'en', true, 'Dividing each term by the previous one yields a value that converges to phi (1.618...).'),
('general', 5, 'What is Heisenberg''s uncertainty principle?', 'You cannot simultaneously know the exact position and momentum of a particle', ARRAY['Observation always modifies the result of an experiment', 'Nothing can exceed the speed of light', 'Energy cannot be created or destroyed'], 'en', true, 'This fundamental quantum mechanics principle was formulated in 1927.'),
('general', 5, 'What is the Fermi paradox?', 'The contradiction between the high probability of extraterrestrial civilizations and the lack of contact', ARRAY['The impossibility of traveling faster than light', 'The accelerating expansion of the universe', 'The contradiction between relativity and quantum mechanics'], 'en', true, 'Enrico Fermi asked: If the universe is so large, where are the extraterrestrials?'),
('general', 5, 'Which millennium prize problem was solved by Grigori Perelman?', 'The Poincare conjecture', ARRAY['The Riemann hypothesis', 'The P vs NP problem', 'The Navier-Stokes equations'], 'en', true, 'Perelman proved the Poincare conjecture in 2003 and refused the Fields Medal.'),
('general', 5, 'What is quantum entanglement?', 'An instantaneous correlation between particles regardless of distance', ARRAY['The superposition of quantum states', 'A particle passing through a barrier', 'The annihilation of a particle and its antiparticle'], 'en', true, 'Einstein called this phenomenon spooky action at a distance.'),
('general', 5, 'What is the constant that measures the expansion rate of the universe?', 'The Hubble constant', ARRAY['The Planck constant', 'The Boltzmann constant', 'The cosmological constant'], 'en', true, 'The Hubble constant is about 70 km/s/Mpc and is subject to ongoing scientific debate.'),
('general', 5, 'What is Godel''s incompleteness theorem?', 'Any consistent formal system contains undecidable propositions', ARRAY['Every mathematical theory contains errors', 'Mathematics cannot describe reality', 'There are numbers that cannot be computed'], 'en', true, 'Kurt Godel proved this theorem in 1931, revolutionizing mathematical logic.'),
('general', 5, 'What is an event horizon?', 'The boundary of a black hole beyond which nothing can escape', ARRAY['The edge of the observable universe', 'The farthest point light has reached', 'The maximum distance between two galaxies'], 'en', true, 'Beyond the event horizon, even light cannot escape the gravity of the black hole.'),
('general', 5, 'What is the twin paradox in special relativity?', 'A twin traveling at high speed ages slower than the one who stayed on Earth', ARRAY['Two twins cannot be born at the same instant', 'An object''s mass decreases with speed', 'Time stops at the speed of light'], 'en', true, 'This paradox illustrates the time dilation predicted by Einstein''s theory.'),
('general', 5, 'What theorem did Andrew Wiles prove in 1995?', 'Fermat''s Last Theorem', ARRAY['The generalized Pythagorean theorem', 'Gauss''s grand theorem', 'The fundamental theorem of algebra'], 'en', true, 'The theorem states that a^n + b^n = c^n has no integer solution for n greater than 2.'),
('general', 5, 'What is the critical density of the universe?', 'About 9.47 x 10^-27 kg/m3', ARRAY['About 1 kg/m3', 'About 10^-10 kg/m3', 'About 10^-35 kg/m3'], 'en', true, 'The critical density determines whether the universe is open, closed, or flat.'),
('general', 5, 'What is the oldest known literary text?', 'The Epic of Gilgamesh', ARRAY['Homer''s Iliad', 'The Vedas', 'The Egyptian Book of the Dead'], 'en', true, 'The Epic of Gilgamesh dates from about 2100 BC and comes from Mesopotamia.'),
('general', 5, 'What is the process by which stars produce energy?', 'Nuclear fusion', ARRAY['Nuclear fission', 'Combustion', 'Radioactivity'], 'en', true, 'Stars fuse hydrogen into helium, releasing enormous amounts of energy.'),
('general', 5, 'What is Schrodinger''s cat thought experiment about?', 'A cat is simultaneously dead and alive until observed', ARRAY['A cat can pass through a wall by quantum tunneling', 'A cat can teleport between two boxes', 'A cat ages more slowly when in motion'], 'en', true, 'This experiment illustrates the apparent absurdity of quantum superposition applied to the macroscopic world.'),
('general', 5, 'What is the approximate mass of a proton?', '1.67 x 10^-27 kg', ARRAY['9.11 x 10^-31 kg', '1.67 x 10^-24 kg', '6.64 x 10^-27 kg'], 'en', true, 'The proton is about 1,836 times more massive than the electron.'),
('general', 5, 'What is the trolley problem?', 'An ethical dilemma about diverting a trolley to save five people but kill one', ARRAY['A mathematical optimization problem', 'A physics thought experiment about momentum', 'A logic puzzle about parallel tracks'], 'en', true, 'The trolley problem was formulated by Philippa Foot in 1967 to explore ethics.'),
('general', 5, 'What is the temperature of the cosmic microwave background radiation?', 'About 2.7 Kelvin', ARRAY['About 0 Kelvin', 'About 10 Kelvin', 'About 100 Kelvin'], 'en', true, 'The cosmic microwave background is a remnant of the Big Bang discovered in 1965.'),
('general', 5, 'What is Goldbach''s conjecture?', 'Every even number greater than 2 is the sum of two prime numbers', ARRAY['Every odd number is the product of two primes', 'There are infinitely many twin primes', 'Every number has a unique prime factorization'], 'en', true, 'Formulated in 1742 by Christian Goldbach, it remains unproven to this day.'),
('general', 5, 'What is the second law of thermodynamics?', 'The entropy of an isolated system can only increase', ARRAY['Energy cannot be created or destroyed', 'At absolute zero entropy is zero', 'Heat flows from hot to cold objects'], 'en', true, 'This law explains why natural processes are irreversible.'),
('general', 5, 'What is the singularity at the center of a black hole?', 'A point of infinite density and spacetime curvature', ARRAY['The event horizon', 'The ergosphere', 'The photosphere'], 'en', true, 'At the singularity, density and spacetime curvature become infinite according to general relativity.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('literature', 1, 'Qui a ecrit Romeo et Juliette ?', 'William Shakespeare', ARRAY['Moliere', 'Victor Hugo', 'Charles Dickens'], 'fr', true, 'Shakespeare a ecrit cette tragedie d''amour vers 1595.'),
('literature', 1, 'Quel est le titre du premier livre de la saga Harry Potter ?', 'Harry Potter a l''ecole des sorciers', ARRAY['Harry Potter et la Chambre des secrets', 'Harry Potter et le Prisonnier d''Azkaban', 'Harry Potter et la Coupe de feu'], 'fr', true, 'Le premier tome a ete publie par J.K. Rowling en 1997.'),
