('literature', 1, 'Qui a ecrit la fable Le Corbeau et le Renard ?', 'Jean de La Fontaine', ARRAY['Charles Perrault', 'Esope', 'Moliere'], 'fr', true, 'La Fontaine s''est inspire des fables d''Esope pour ecrire cette celebre fable en 1668.'),
('literature', 1, 'Quel est le prenom de Mademoiselle Granger dans Harry Potter ?', 'Hermione', ARRAY['Ginny', 'Luna', 'Cho'], 'fr', true, 'Hermione Granger est l''une des meilleures amies de Harry Potter et une sorciere brillante.'),
('literature', 1, 'Quel personnage de conte perd sa pantoufle de verre ?', 'Cendrillon', ARRAY['Blanche-Neige', 'La Belle au bois dormant', 'Raiponce'], 'fr', true, 'Cendrillon perd sa pantoufle en fuyant le bal a minuit dans le conte de Perrault.'),
('literature', 1, 'Qui a ecrit la serie de BD Asterix ?', 'Rene Goscinny et Albert Uderzo', ARRAY['Herge', 'Peyo', 'Franquin'], 'fr', true, 'Goscinny ecrivait les scenarii et Uderzo dessinait les aventures du celebre Gaulois.'),
('literature', 1, 'Quel est le nom du chien de Tintin ?', 'Milou', ARRAY['Idefix', 'Rantanplan', 'Pluto'], 'fr', true, 'Milou est un fox-terrier blanc qui accompagne Tintin dans toutes ses aventures.'),
('literature', 1, 'Qui a ecrit Le Seigneur des Anneaux ?', 'J.R.R. Tolkien', ARRAY['C.S. Lewis', 'J.K. Rowling', 'George R.R. Martin'], 'fr', true, 'Tolkien a publie cette trilogie epique entre 1954 et 1955.'),
('literature', 1, 'Comment s''appelle la sorciere dans le conte d''Hansel et Gretel ?', 'La sorciere de la maison en pain d''epice', ARRAY['Maléfique', 'La Reine mechante', 'Baba Yaga'], 'fr', true, 'Dans ce conte des freres Grimm, la sorciere attire les enfants avec sa maison en sucreries.'),
('literature', 1, 'Quel est le nom du petit elephant dans les livres de Jean de Brunhoff ?', 'Babar', ARRAY['Dumbo', 'Elmer', 'Horton'], 'fr', true, 'Babar est un personnage de litterature jeunesse cree en 1931.'),
('literature', 1, 'Qui a ecrit Charlie et la Chocolaterie ?', 'Roald Dahl', ARRAY['J.K. Rowling', 'Lewis Carroll', 'Enid Blyton'], 'fr', true, 'Roald Dahl a publie ce livre pour enfants en 1964.'),
('literature', 1, 'Quel animal parle dans la fable La Cigale et la Fourmi ?', 'La cigale et la fourmi', ARRAY['Le lion et le rat', 'Le loup et l''agneau', 'Le corbeau et le renard'], 'fr', true, 'Cette fable de La Fontaine met en scene une cigale imprevoyante et une fourmi travailleuse.'),
('literature', 1, 'Quel est le nom du pantin de bois qui veut devenir un vrai garcon ?', 'Pinocchio', ARRAY['Geppetto', 'Jiminy Cricket', 'Peter Pan'], 'fr', true, 'Pinocchio est un personnage cree par Carlo Collodi en 1881.'),
('literature', 1, 'Qui a ecrit Le Monde de Narnia ?', 'C.S. Lewis', ARRAY['J.R.R. Tolkien', 'J.K. Rowling', 'Philip Pullman'], 'fr', true, 'C.S. Lewis a publie cette serie de 7 livres entre 1950 et 1956.'),
('literature', 1, 'Quel est le nom de la fee dans La Belle au bois dormant ?', 'La fee Carabosse', ARRAY['La fee Clochette', 'La Bonne Fee', 'La fee Morgane'], 'fr', true, 'La fee Carabosse est la mechante fee qui jette un sort a la princesse.'),
('literature', 1, 'Qui a ecrit Les Malheurs de Sophie ?', 'La Comtesse de Segur', ARRAY['George Sand', 'Colette', 'Madame de Lafayette'], 'fr', true, 'La Comtesse de Segur a ecrit ce classique de la litterature enfantine en 1858.'),
('literature', 1, 'Comment s''appelle le hobbit dans le roman de Tolkien ?', 'Bilbo Baggins', ARRAY['Frodon Sacquet', 'Gandalf', 'Aragorn'], 'fr', true, 'Le Hobbit, publie en 1937, raconte les aventures de Bilbo Sacquet.'),
('literature', 1, 'Quel auteur a cree le personnage de Fantomette ?', 'Georges Chaulet', ARRAY['Enid Blyton', 'Rene Goscinny', 'Marcel Ayme'], 'fr', true, 'Fantomette est une heroine de la Bibliotheque Rose creee en 1961.'),
('literature', 1, 'Comment s''appelle le dragon dans l''Histoire sans fin ?', 'Falkor', ARRAY['Smaug', 'Drago', 'Toothless'], 'fr', true, 'Falkor est un dragon porte-bonheur dans le roman de Michael Ende.'),
('literature', 1, 'Quel est le nom de famille de la celebre detective Miss Marple ?', 'Marple', ARRAY['Holmes', 'Poirot', 'Fletcher'], 'fr', true, 'Miss Marple est un personnage cree par Agatha Christie en 1930.'),
('literature', 1, 'Qui a ecrit Les Chroniques de Narnia : Le Lion, la Sorciere blanche et l''Armoire magique ?', 'C.S. Lewis', ARRAY['J.R.R. Tolkien', 'Roald Dahl', 'Philip Pullman'], 'fr', true, 'C''est le premier roman des Chroniques de Narnia publie en 1950.'),
('literature', 1, 'Quel est le titre du celebre livre de Roald Dahl sur un enorme fruit ?', 'James et la Grosse Peche', ARRAY['Charlie et la Chocolaterie', 'Matilda', 'Le Bon Gros Geant'], 'fr', true, 'Roald Dahl a publie ce conte fantastique en 1961.'),
('literature', 1, 'Qui est l''auteur du Petit Nicolas ?', 'Rene Goscinny', ARRAY['Marcel Pagnol', 'Marcel Ayme', 'Saint-Exupery'], 'fr', true, 'Goscinny a ecrit les histoires du Petit Nicolas, illustrees par Sempe.'),
