('literature', 1, 'Quel est le genre litteraire de Cendrillon ?', 'Le conte de fees', ARRAY['Le roman', 'La fable', 'La legende'], 'fr', true, 'Cendrillon est un conte de fees populaire raconte par Perrault et les freres Grimm.'),
('literature', 1, 'Qui a ecrit la serie de livres Le Club des Cinq ?', 'Enid Blyton', ARRAY['Roald Dahl', 'J.K. Rowling', 'Astrid Lindgren'], 'fr', true, 'Enid Blyton a cree cette serie d''aventures en 1942 avec 21 tomes.'),
('literature', 1, 'Quel est le nom du chien dans la serie Tintin ?', 'Milou', ARRAY['Idefix', 'Rex', 'Rantanplan'], 'fr', true, 'Milou accompagne Tintin dans toutes ses aventures depuis 1929.'),
