('literature', 1, 'Qui a ecrit Fifi Brindacier ?', 'Astrid Lindgren', ARRAY['Enid Blyton', 'Roald Dahl', 'La Comtesse de Segur'], 'fr', true, 'Astrid Lindgren a cree le personnage de Fifi Brindacier en 1945 en Suede.'),
('literature', 1, 'Quel est le nom du magicien dans Le Seigneur des Anneaux ?', 'Gandalf', ARRAY['Saroumane', 'Dumbledore', 'Merlin'], 'fr', true, 'Gandalf le Gris, puis Gandalf le Blanc, guide la Communaute de l''Anneau.'),
('literature', 1, 'Qui a ecrit Le Journal d''Anne Frank ?', 'Anne Frank', ARRAY['Simone de Beauvoir', 'Helen Keller', 'Virginia Woolf'], 'fr', true, 'Anne Frank a ecrit son journal pendant la Seconde Guerre mondiale alors qu''elle se cachait a Amsterdam.'),
('literature', 1, 'Comment s''appelle la petite fille dans Heidi ?', 'Heidi', ARRAY['Clara', 'Gretel', 'Sophie'], 'fr', true, 'Heidi est un roman de Johanna Spyri publie en 1880, se deroulant dans les Alpes suisses.'),
('literature', 1, 'Quel animal est le personnage principal de Stuart Little ?', 'Une souris', ARRAY['Un rat', 'Un chat', 'Un lapin'], 'fr', true, 'Stuart Little est une souris nee dans une famille humaine, creee par E.B. White en 1945.'),
('literature', 1, 'Qui a ecrit La Toile de Charlotte ?', 'E.B. White', ARRAY['Roald Dahl', 'Beatrix Potter', 'A.A. Milne'], 'fr', true, 'E.B. White a publie cette histoire d''amitie entre une araignee et un cochon en 1952.'),
('literature', 1, 'Comment s''appelle l''ours dans Winnie l''Ourson ?', 'Winnie', ARRAY['Tigrou', 'Porcinet', 'Bourriquet'], 'fr', true, 'Winnie l''Ourson a ete cree par A.A. Milne en 1926 et adore le miel.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('literature', 2, 'Qui a ecrit Les Miserables ?', 'Victor Hugo', ARRAY['Emile Zola', 'Alexandre Dumas', 'Gustave Flaubert'], 'fr', true, 'Victor Hugo a publie Les Miserables en 1862, un chef-d''oeuvre du romantisme francais.'),
('literature', 2, 'Quel auteur a cree le personnage de Sherlock Holmes ?', 'Arthur Conan Doyle', ARRAY['Agatha Christie', 'Edgar Allan Poe', 'Charles Dickens'], 'fr', true, 'Sherlock Holmes est apparu pour la premiere fois en 1887 dans Une Etude en rouge.'),
