('literature', 2, 'Qui a ecrit Les Trois Mousquetaires ?', 'Alexandre Dumas', ARRAY['Victor Hugo', 'Honore de Balzac', 'Emile Zola'], 'fr', true, 'Alexandre Dumas a publie ce roman de cape et d''epee en 1844.'),
('literature', 2, 'Quel est le vrai nom d''Arsene Lupin ?', 'Arsene Lupin', ARRAY['Raoul d''Andresy', 'Paul Sernine', 'Don Luis Perenna'], 'fr', true, 'Arsene Lupin utilise de nombreux pseudonymes, mais Raoul d''Andresy est un de ses alias principaux.'),
('literature', 2, 'Qui a cree le personnage du Petit Prince ?', 'Antoine de Saint-Exupery', ARRAY['Victor Hugo', 'Marcel Pagnol', 'Jules Verne'], 'fr', true, 'Le Petit Prince a ete publie en 1943 a New York par Saint-Exupery.'),
('literature', 2, 'Quel roman de Jules Verne raconte un voyage au centre de la Terre ?', 'Voyage au centre de la Terre', ARRAY['De la Terre a la Lune', 'Vingt Mille Lieues sous les mers', 'Le Tour du monde en 80 jours'], 'fr', true, 'Ce roman de 1864 suit le professeur Lidenbrock dans une expedition souterraine.'),
('literature', 2, 'Qui a ecrit Le Comte de Monte-Cristo ?', 'Alexandre Dumas', ARRAY['Victor Hugo', 'Stendhal', 'Honore de Balzac'], 'fr', true, 'Le Comte de Monte-Cristo a ete publie en 1844 et raconte la vengeance d''Edmond Dantes.'),
