INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('literature', 5, 'Qui a recu le prix Nobel de litterature en 2023 ?', 'Jon Fosse', ARRAY['Annie Ernaux', 'Abdulrazak Gurnah', 'Louise Gluck'], 'fr', true, 'L''ecrivain et dramaturge norvegien Jon Fosse a recu le Nobel en 2023 pour ses oeuvres innovantes.'),
('literature', 5, 'Quel roman de Georges Perec est ecrit sans utiliser la lettre E ?', 'La Disparition', ARRAY['W ou le Souvenir d''enfance', 'Les Choses', 'La Vie mode d''emploi'], 'fr', true, 'La Disparition, publie en 1969, est un lipogramme en E de 300 pages.'),
('literature', 5, 'Quel est le concept d''intertextualite theorise par Julia Kristeva ?', 'Le fait que tout texte est un tissu de references a d''autres textes', ARRAY['L''impossibilite de toute creation originale', 'La relation entre un auteur et son lecteur', 'Le plagiat conscient entre ecrivains'], 'fr', true, 'Kristeva a defini l''intertextualite en 1966 en s''inspirant des travaux de Bakhtine.'),
