('literature', 5, 'Quel est le nom de la technique narrative utilisee par James Joyce dans Ulysse ?', 'Le courant de conscience (stream of consciousness)', ARRAY['Le monologue interieur classique', 'La narration omnisciente', 'Le point de vue multiple'], 'fr', true, 'Joyce utilise le courant de conscience pour retranscrire le flux de pensees de ses personnages.'),
('literature', 5, 'Quel auteur argentine a ecrit Fictions ?', 'Jorge Luis Borges', ARRAY['Julio Cortazar', 'Gabriel Garcia Marquez', 'Ernesto Sabato'], 'fr', true, 'Borges a publie ce recueil de nouvelles en 1944, melant philosophie et fantastique.'),
('literature', 5, 'Qui a ecrit Les Versets sataniques ?', 'Salman Rushdie', ARRAY['Naguib Mahfouz', 'Orhan Pamuk', 'V.S. Naipaul'], 'fr', true, 'Rushdie a publie ce roman en 1988, provoquant une fatwa de l''ayatollah Khomeini.'),
('literature', 5, 'Quel est le concept de defamiliarisation en theorie litteraire ?', 'Rendre etrange le familier pour renouveler la perception du lecteur', ARRAY['Eviter les cliches narratifs', 'Supprimer toute reference culturelle', 'Ecrire dans une langue etrangere'], 'fr', true, 'Victor Chklovski a theorise ce concept en 1917 dans L''Art comme procede.'),
('literature', 5, 'Qui a ecrit Le Bruit et la Fureur ?', 'William Faulkner', ARRAY['Ernest Hemingway', 'John Steinbeck', 'F. Scott Fitzgerald'], 'fr', true, 'Faulkner a publie ce roman en 1929, utilisant des techniques narratives novatrices.'),
('literature', 5, 'Quel est le premier roman ecrit entierement par une femme en France ?', 'La Princesse de Cleves', ARRAY['Les Lettres persanes', 'Julie ou la Nouvelle Heloise', 'Corinne'], 'fr', true, 'Madame de Lafayette a publie La Princesse de Cleves en 1678, premier roman psychologique.'),
('literature', 5, 'Quel auteur nigerien a ecrit Les Soleils des independances ?', 'Ahmadou Kourouma', ARRAY['Chinua Achebe', 'Wole Soyinka', 'Ngugi wa Thiong''o'], 'fr', true, 'Kourouma a publie ce roman en 1968, pionnier de la litterature africaine francophone.');
