INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('literature', 5, 'Who won the Nobel Prize in Literature in 2023?', 'Jon Fosse', ARRAY['Annie Ernaux', 'Abdulrazak Gurnah', 'Louise Gluck'], 'en', true, 'Norwegian writer and playwright Jon Fosse received the Nobel in 2023 for his innovative works.'),
